import { DOCUMENT } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  input,
  output,
  signal,
} from '@angular/core';

@Component({
  selector: 'aevko-code-block',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './code-block.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { '[attr.data-variant]': 'variant()', '[attr.data-size]': 'size()' },
})
export class AevkoCodeBlock {
  readonly variant = input<'default' | 'destructive'>('default');
  readonly size = input<'default' | 'sm'>('default');
}

@Component({
  selector: 'aevko-code-block-header',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './code-block-header.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AevkoCodeBlockHeader {}

@Component({
  selector: 'aevko-code-block-content',
  standalone: true,
  templateUrl: './code-block-content.component.html',
  styleUrl: './code-block-content.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { '[attr.data-wrap]': 'wrap()' },
})
export class AevkoCodeBlockContent {
  readonly code = input('');
  readonly language = input('text');
  readonly lineNumbers = input(false);
  readonly startLine = input(1);
  readonly wrap = input(false);
  protected readonly lines = computed(() => this.code().split('\n'));
}

@Component({
  selector: 'aevko-code-block-line',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './code-block-line.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { '[attr.data-variant]': 'variant()' },
})
export class AevkoCodeBlockLine {
  readonly variant = input<'default' | 'added' | 'removed' | 'highlighted'>('default');
}

@Component({
  selector: 'button[aevkoCodeBlockCopy]',
  standalone: true,
  template: '{{ copied() ? "Copied" : "Copy" }}',
  styleUrl: './code-block-copy.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    type: 'button',
    '[attr.aria-label]': 'copied() ? "Code copied" : "Copy code"',
    '(click)': 'copy()',
  },
})
export class AevkoCodeBlockCopy {
  readonly value = input.required<string>();
  readonly copiedChange = output<void>();
  protected readonly copied = signal(false);
  private readonly document = inject(DOCUMENT);

  protected async copy(): Promise<void> {
    const clipboard = this.document.defaultView?.navigator.clipboard;
    if (!clipboard) return;
    await clipboard.writeText(this.value());
    this.copied.set(true);
    this.copiedChange.emit();
    this.document.defaultView?.setTimeout(() => this.copied.set(false), 1500);
  }
}

@Component({
  selector: 'aevko-code-block-footer',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './code-block-footer.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AevkoCodeBlockFooter {}

:host {
  background: var(--aevko-surface, #f4f4f5);
  border: 1px solid var(--aevko-border, #e4e4e7);
  border-radius: var(--aevko-radius, 0);
  color: var(--aevko-foreground, #09090b);
  display: block;
  overflow: hidden;
}
:host([data-variant='destructive']) {
  border-color: var(--aevko-danger, #3f3f3f);
}
:host([data-size='sm']) {
  font-size: 0.8125rem;
}

:host {
  align-items: center;
  border-bottom: 1px solid var(--aevko-border, #e4e4e7);
  display: flex;
  font: 650 0.8125rem/1 var(--aevko-font-sans, sans-serif);
  justify-content: space-between;
  min-height: 2.75rem;
  padding-inline: 0.875rem;
}

:host {
  display: block;
}
pre {
  margin: 0;
  overflow: auto;
  padding: 1rem;
}
pre:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: -3px;
}
code {
  font: 500 0.875rem/1.6 var(--aevko-font-mono, monospace);
  white-space: pre;
}
:host([data-wrap='true']) code {
  white-space: pre-wrap;
  word-break: break-word;
}
.line {
  display: block;
}
.line::before {
  color: var(--aevko-muted, #71717a);
  content: attr(data-line);
  display: inline-block;
  margin-inline-end: 1rem;
  min-width: 2ch;
  text-align: end;
  user-select: none;
}

:host {
  display: block;
  padding-inline: 1rem;
}
:host([data-variant='highlighted']) {
  background: color-mix(in srgb, var(--aevko-foreground, #09090b) 7%, transparent);
}
:host([data-variant='added'])::before {
  content: '+ ';
}
:host([data-variant='removed'])::before {
  content: '- ';
}

:host {
  background: transparent;
  border: 1px solid var(--aevko-border-strong, #a1a1aa);
  border-radius: var(--aevko-radius, 0);
  color: inherit;
  cursor: pointer;
  font: inherit;
  min-height: 2rem;
  padding-inline: 0.625rem;
}
:host:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}

:host {
  align-items: center;
  border-top: 1px solid var(--aevko-border, #e4e4e7);
  display: flex;
  min-height: 2.75rem;
  padding-inline: 0.875rem;
}
